# ABSTRACT: Which PCI subsystem IDs mark an NVIDIA vGPU guest device

package Rex::GPU::NVIDIA::VGPU;
our $VERSION = '0.002';
use v5.14.4;
use warnings;


sub type_for {
  my ( $self, $device_id, $subsystem_id, $subsystem_vendor_id ) = @_;
  return unless defined $device_id && $device_id =~ /\A[0-9a-f]{4}\z/i;
  return unless defined $subsystem_id && $subsystem_id =~ /\A[0-9a-f]{4}\z/i;
  return if defined $subsystem_vendor_id && lc $subsystem_vendor_id ne '10de';
  my %types = $self->types;
  return $types{ lc($device_id).':'.lc($subsystem_id) };
}

